// The day's affirmation in Norwegian (Bokmål), for the country pages in Norwegian (Bokmål). Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Du trenger ikke rekke alt i dag. Den neste lille tingen er nok.\", \"Å være sliten er ikke det samme som å mislykkes. Du er sliten fordi du stiller opp, dag etter dag.\", \"Oppvasken kan vente. Du har lov til å sette deg i fem minutter.\", \"Frokostblanding til middag teller også som å gi familien mat.\", \"Hvile er ikke noe du må gjøre deg fortjent til. Du har lov til å hvile nå.\", \"Noen dager er seieren at alle kom seg helt til leggetid. Det er en ekte seier.\", \"Du gjør mer enn noen ser. Jeg ser det.\", \"Et rotete hus og elskede barn. Det er et godt bytte.\", \"På en tung dag ser ditt beste annerledes ut, og det teller fortsatt.\", \"Ett dypt pust. Senk skuldrene. Du gjør det bra.\", \"Det er greit å senke listen i dag. Du kan heve den igjen en annen dag.\", \"Å be om hjelp er sterkt, ikke svakt.\", \"Du har lov til å si nei til én ting til.\", \"Hvis du følte deg ensom i dag, er du ikke den eneste moren som har kjent det slik. Vi er mange.\", \"Du fortjener en venninne som spør hvordan du har det, og venter på svaret.\", \"Det er greit å ta kontakt først. De fleste mødre håper at noen gjør det.\", \"Å føle seg oversett betyr ikke at du ikke betyr noe. Du betyr veldig mye.\", \"Følelsene dine gir mening. Du er ikke for mye.\", \"Her trenger du ikke forklare den tunge dagen din. Vi skjønner det.\", \"En melding til en annen mor der det står «meg også», kan snu en hel dag.\", \"Mate, skifte, vugge, og så på nytt. Det er ekte arbeid, selv når det ser ut som å sitte stille.\", \"Du og babyen din holder fortsatt på å bli kjent. Det haster ikke.\", \"Dagene med en nyfødt er lange. Denne perioden varer ikke evig.\", \"Hvis alt du gjorde i dag var å holde et lite menneske mett og varmt, har du gjort en stor jobb.\", \"Du trenger ikke komme deg raskt tilbake. Du kan bare være der du er.\", \"Uansett hvordan babyen din får mat, tar du vare på babyen din. Det er det som teller.\", \"Du kan mangle søvn og være full av kjærlighet på samme tid.\", \"Hold babyen og la huset være. Huset er der fortsatt.\", \"Et raserianfall i butikken gjør deg ikke til en dårlig mor. Det betyr bare at du har et lite barn.\", \"De små tester grensene fordi de føler seg trygge hos deg.\", \"Du holdt deg rolig ett minutt lenger enn i går. Det teller.\", \"Hvis du mistet besinnelsen, retter en klem og et «unnskyld» opp mye. Og det lærer dem noe fint.\", \"Klissete hender, høye stemmer, store følelser. Du oppdrar et helt menneske.\", \"Det femte «hvorfor?» denne timen er et lite hode som vokser.\", \"Du trenger ikke en perfekt dag for å lage et godt minne.\", \"En dør som smelles igjen, er ikke slutten på historien. La lyset stå på.\", \"Tenåringen din sier det kanskje ikke, men det betyr noe at du alltid er der.\", \"Å være den rolige i huset er hardt arbeid. Og du gjør det.\", \"Noen av de beste samtalene skjer i bilen. Bare fortsett å kjøre.\", \"De trekker seg unna for å bli voksne, ikke for å forlate deg.\", \"Du trenger ikke ha alle svarene. Å lytte er en stor del av det.\", \"Store barn trenger deg fortsatt, bare på stillere måter.\", \"Å klare alt alene krever en styrke de fleste aldri ser.\", \"Du er mamma nok for barnet ditt. Det har du alltid vært.\", \"Ett par hender, hundre oppgaver. Vær snill med deg selv.\", \"Barna dine lærer, ved å se på deg, hvordan et sterkt og kjærlig menneske er.\", \"En pause er ikke å forlate posten din. Det er slik du holder ut.\", \"Ingen fører regnskap. Kjærlighet og å være der er det som betyr noe.\", \"Sorg og kjærlighet kommer fra samme sted. Å savne noen viser hvor høyt du har elsket.\", \"Det finnes ingen riktig tidsplan for sorg. Ta den tiden du trenger.\", \"På de tunge merkedagene, vær like snill med deg selv som du ville vært med en venninne.\", \"Du kan bære på sorg og likevel le med barna dine. Begge deler er ekte.\", \"Hvis du har mistet et svangerskap eller en baby, er det tapet ekte, og det er kjærligheten din også.\", \"Noen dager er sorgen stille, andre dager er den høylytt. Begge deler er greit.\", \"Lite penger betyr ikke lite kjærlighet.\", \"Barna dine vil huske tiden med deg mer enn tingene du kjøpte.\", \"Å spørre om hjelp med regningene er klokt, ikke skamfullt. Det er det hjelpen er der for.\", \"En gratis ettermiddag i parken kan bli ukens beste dag.\", \"Du fikk pengene til å strekke til en uke til. Det krever ekte dyktighet.\", \"Pengebekymringer sliter. Du bærer mye, og du er fortsatt her.\", \"Du drakk et glass vann i dag. Begynn der.\", \"Alle kom seg ut døra. Skoene passet kanskje ikke sammen. Likevel en seier.\", \"Du tok den telefonen du gruet deg til. Det var modig.\", \"Du lo i dag. Hold fast på det.\", \"Et varmt måltid, en ren T-skjorte, en godnatthistorie. Små ting blir til en barndom.\", \"I dag var du snill mot noen, selv om det bare var deg selv.\", \"Fremgang, ikke perfeksjon. Du kom et steg videre i dag.\", \"Du ble ferdig med én ting på listen. Det er én mer enn ingen.\", \"Du er en god mamma. At du bekymrer deg for det, viser hvor mye du bryr deg.\", \"Du er mer enn det du rekker på en dag.\", \"Barna dine trenger ikke en perfekt mamma. De trenger deg, og de har deg.\", \"Vær like tålmodig med deg selv som du er med barna dine.\", \"Du har lov til å ta plass, ønske deg ting og ha dine egne drømmer.\", \"En feil visker ikke ut kjærlighet. I morgen er en ny start.\", \"Du er hele verden for noen, og du er også ditt eget menneske.\", \"Det er greit å ikke nyte hvert eneste minutt. Du kan likevel elske barna dine av hele ditt hjerte.\", \"Det finnes ikke én riktig måte å være mamma på. Din måte er også god.\", \"Som i trestillingen er det greit å vakle. Du kan finne balansen igjen.\", \"Plant føttene som i fjellstillingen. Du står stødigere enn du føler.\", \"Kriger to: sterke bein, åpne armer. Det er deg, når du møter denne uka.\", \"Pust inn på fire, ut på fire. Du er her, og du gjør det bra.\", \"Strekk deg bredt som en stjerne. Du har lov til å ta plass.\", \"En bred, dyp knebøy er tung å holde. Det samme er en lang dag. Og du holder ut.\", \"Du kan bøye deg som en månesigd og fortsatt stå.\", \"Du trenger ikke nå tærne ennå. Hver lille bit av tøyningen teller.\", \"Trekantstilling: én hånd ned, én hånd opp. Stå støtt og fortsett å strekke deg.\", \"Det er sent. Det som ikke ble gjort i dag, kan vente til i morgen.\", \"Oppe med babyen på denne tiden? Mange mødre er våkne sammen med deg akkurat nå.\", \"Huset er stille. Dette øyeblikket er ditt. Pust.\", \"Du kom deg gjennom dagen i dag. Det var alt dagen trengte.\", \"Hvis tankene kverner i natt, skriv dem ned og la dem vente til i morgen tidlig.\", \"Hvil øynene. I morgen kan du begynne på nytt.\", \"Høytider kan være tunge og glade på en gang. Uansett hvordan denne tiden kjennes for deg, er det greit.\", \"Bordet trenger ikke være perfekt. Det er menneskene rundt det som betyr noe.\", \"Hvis du savner noen rundt bordet i år, vær forsiktig med hjertet ditt.\", \"Takk, mamma, for hvert måltid, hver kjøretur og hver klem.\", \"Du trenger ikke være vertinne, bake eller smile hele veien. En enkel høytid er fortsatt en høytid.\", \"Den beste gaven barna dine får i år, er tid med deg.\", \"En liten jul er fortsatt full av kjærlighet. Det trengs ikke mye penger for å gjøre den spesiell.\", \"Kalde dager, varme klemmer. Du er det varme stedet i hjemmet ditt.\", \"Det er greit å hoppe over noe av førjulsstresset. Ro er også en gave.\", \"Hvis høytiden er tung for deg i år, er du ikke alene. Ta én dag om gangen.\"]";D.body.appendChild(e)})();
